import type OpenAI from 'openai';
import { StructuredLogger } from '../logging/structured-logger';
import type { AgentRuntimeContextService } from './agent-runtime';
import type { ToolArgs } from './unified-agent.types';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { PrismaService } from '../prisma/prisma.service';
import type { AuditService } from '../audit/audit.service';
import type { RiskGateService } from './risk-class/risk-gate.service';

type UnknownRecord = Record<string, unknown>;

function str(v: unknown, fb = ''): string {
  return typeof v === 'string'
    ? v
    : typeof v === 'number' || typeof v === 'boolean'
      ? String(v)
      : fb;
}

export function num(v: unknown, fb = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n) : fb;
}

export function actionSucceeded(result: unknown): boolean {
  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    return false;
  }
  const record = result as Record<string, unknown>;
  return record.success === true || record.ok === true || record.executed === true;
}

export function buildAgentToolEnvelope(
  agentRuntime: AgentRuntimeContextService | undefined,
  params: {
    workspaceId: string;
    toolName: string;
  },
): { id: string; toolName: string; allowed: boolean } {
  return (
    agentRuntime?.buildToolEnvelope(params) ?? {
      id: 'agent-runtime-unavailable',
      toolName: params.toolName,
      allowed: true,
    }
  );
}

export interface ExecuteToolActionDeps {
  logger: StructuredLogger;
  actions: UnifiedAgentActionsService;
  prisma: PrismaService;
  auditService: AuditService;
  riskGate?: RiskGateService;
  agentRuntime?: AgentRuntimeContextService;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
}

export async function executeToolAction(
  deps: ExecuteToolActionDeps,
  workspaceId: string,
  contactId: string,
  phone: string,
  tool: string,
  args: ToolArgs,
  context?: UnknownRecord,
): Promise<unknown> {
  deps.logger.log(`Executing tool: ${tool}`, { args });
  const envelope = buildAgentToolEnvelope(deps.agentRuntime, {
    workspaceId,
    toolName: tool,
  });

  switch (tool) {
    case 'send_message':
      return deps.actions.actionSendMessage(workspaceId, phone, args, context);
    case 'send_product_info':
      return deps.actions.actionSendProductInfo(workspaceId, phone, args, context);
    case 'create_payment_link': {
      const paymentAmount = num(args.amount);
      if (deps.riskGate && paymentAmount > 0) {
        const gateDecision = deps.riskGate.gatePaymentAction({
          amountCents: paymentAmount,
          reversible: true,
          target: 'lead',
        });
        if (gateDecision.verdict === 'block') {
          deps.logger.error(`R4 BLOCKED: create_payment_link — ${gateDecision.reason}`);
          return {
            success: false,
            blocked: true,
            riskClass: gateDecision.classification.class,
            error: gateDecision.reason,
          };
        }
        if (gateDecision.verdict === 'warn') {
          deps.logger.warn(
            `Risk gate: payment ${gateDecision.classification.class} — ${gateDecision.reason}`,
          );
        }
      }
      const result = await deps.actions.actionCreatePaymentLink(workspaceId, phone, args, context);
      try {
        await deps.prisma.$transaction(
          async (tx) => {
            await deps.auditService.logWithTx(tx, {
              workspaceId,
              action: 'AGENT_DISPATCHED_PAYMENT_LINK',
              resource: 'UnifiedAgent',
              resourceId: contactId,
              details: { tool, phone },
            });
          },
          { isolationLevel: 'ReadCommitted' },
        );
      } catch (auditError: unknown) {
        const auditMsg =
          auditError instanceof Error
            ? auditError.message
            : typeof auditError === 'string'
              ? auditError
              : 'unknown';
        deps.logger.warn(`Audit dispatch log failed: ${auditMsg}`);
      }
      return result;
    }
    case 'update_lead_status':
      return deps.actions.actionUpdateLeadStatus(workspaceId, contactId, args);
    case 'add_tag':
      return deps.actions.actionAddTag(workspaceId, contactId, args);
    case 'schedule_followup':
      return deps.actions.actionScheduleFollowup(workspaceId, contactId, phone, args, context);
    case 'transfer_to_human':
      return deps.actions.actionTransferToHuman(workspaceId, contactId, args, context);
    case 'search_knowledge_base':
      return deps.actions.actionSearchKnowledgeBase(workspaceId, args);
    case 'trigger_flow':
      return deps.actions.actionTriggerFlow(workspaceId, phone, args);
    case 'log_event':
      return deps.actions.actionLogEvent(workspaceId, contactId, args);
    case 'send_media':
      return deps.actions.actionSendMedia(workspaceId, phone, args, context);
    case 'send_document':
      return deps.actions.actionSendDocument(workspaceId, phone, args, context);
    case 'send_voice_note':
      return deps.actions.actionSendVoiceNote(workspaceId, phone, args, context);
    case 'send_audio':
      return deps.actions.actionSendAudio(workspaceId, phone, args, context);
    case 'transcribe_audio':
      return deps.actions.actionTranscribeAudio(workspaceId, args);
    case 'create_product':
      return deps.actions.actionCreateProduct(workspaceId, args);
    case 'update_product':
      return deps.actions.actionUpdateProduct(workspaceId, args);
    case 'get_product_plans':
      return deps.actions.getProductPlans(str(args.productId));
    case 'get_product_ai_config':
      return deps.actions.getProductAIConfig(str(args.productId));
    case 'get_product_reviews':
      return deps.actions.getProductReviews(str(args.productId));
    case 'get_product_urls':
      return deps.actions.getProductUrls(str(args.productId));
    case 'validate_coupon':
      return deps.actions.validateCoupon(str(args.productId), str(args.code));
    case 'create_flow':
      return deps.actions.actionCreateFlow(workspaceId, args);
    case 'update_workspace_settings':
      return deps.actions.actionUpdateWorkspaceSettings(workspaceId, args);
    case 'create_broadcast':
      return deps.actions.actionCreateBroadcast(workspaceId, args, context);
    case 'get_analytics':
      return deps.actions.actionGetAnalytics(workspaceId, args);
    case 'configure_ai_persona':
      return deps.actions.actionConfigureAIPersona(workspaceId, args);
    case 'toggle_autopilot':
      return deps.actions.actionToggleAutopilot(workspaceId, args);
    case 'create_flow_from_description':
      return deps.actions.actionCreateFlowFromDescription(
        workspaceId,
        args,
        deps.openai,
        deps.primaryBrainModel,
        deps.fallbackBrainModel,
      );
    case 'connect_whatsapp':
      return deps.actions.actionConnectWhatsApp(workspaceId, args);
    case 'import_contacts':
      return deps.actions.actionImportContacts(workspaceId, args);
    case 'generate_sales_funnel':
      return deps.actions.actionGenerateSalesFunnel(workspaceId, args);
    case 'schedule_campaign':
      return deps.actions.actionScheduleCampaign(workspaceId, args);
    case 'get_workspace_status':
      return deps.actions.actionGetWorkspaceStatus(workspaceId, args);
    case 'update_billing_info':
      return deps.actions.actionUpdateBillingInfo(workspaceId, args);
    case 'get_billing_status':
      return deps.actions.actionGetBillingStatus(workspaceId);
    case 'change_plan':
      return deps.actions.actionChangePlan(workspaceId, args);
    case 'apply_discount':
      if (deps.riskGate) {
        const gateDecision = deps.riskGate.gateDiscountOffer({
          amountCents: 0,
          reversible: true,
          target: 'lead',
        });
        if (gateDecision.verdict === 'block') {
          deps.logger.error(`R4 BLOCKED: apply_discount — ${gateDecision.reason}`);
          return {
            success: false,
            blocked: true,
            riskClass: gateDecision.classification.class,
            error: gateDecision.reason,
          };
        }
        if (gateDecision.verdict === 'warn') {
          deps.logger.warn(
            `Risk gate: discount ${gateDecision.classification.class} — ${gateDecision.reason}`,
          );
        }
      }
      return deps.actions.actionApplyDiscount(workspaceId, contactId, phone, args, context);
    case 'handle_objection':
      return deps.actions.actionHandleObjection(workspaceId, contactId, phone, args, context);
    case 'qualify_lead':
      return deps.actions.actionQualifyLead(workspaceId, contactId, phone, args, context);
    case 'schedule_meeting':
      return deps.actions.actionScheduleMeeting(workspaceId, contactId, phone, args, context);
    case 'anti_churn_action':
      return deps.actions.actionAntiChurn(workspaceId, contactId, phone, args, context);
    case 'reactivate_ghost':
      return deps.actions.actionReactivateGhost(workspaceId, contactId, phone, args, context);
    default:
      deps.logger.warn(`Unknown tool: ${tool}`);
      return { success: false, error: 'Unknown tool', policyEnvelope: envelope };
  }
}
